import java.util.*;

class Solution {
    public int lengthOfLongestSubstringKDistinct(String s, int k) {
        if (k == 0 || s.isEmpty()) {
            return 0;
        }

        Map<Character, Integer> count = new HashMap<>();
        int best = 0;
        int left = 0;

        for (int right = 0; right < s.length(); right++) {
            char ch = s.charAt(right);
            count.put(ch, count.getOrDefault(ch, 0) + 1);

            while (count.size() > k) {
                char outgoing = s.charAt(left);
                int next = count.get(outgoing) - 1;
                if (next == 0) {
                    count.remove(outgoing);
                } else {
                    count.put(outgoing, next);
                }
                left++;
            }

            best = Math.max(best, right - left + 1);
        }

        return best;
    }
}

class Solution {
    public int lengthOfLongestSubstringKDistinct(String s, int k) {
        if (k == 0 || s.isEmpty()) {
            return 0;
        }

        int[] count = new int[128];
        int distinct = 0;
        int best = 0;
        int left = 0;

        for (int right = 0; right < s.length(); right++) {
            char ch = s.charAt(right);
            if (count[ch] == 0) {
                distinct++;
            }
            count[ch]++;

            while (distinct > k) {
                char outgoing = s.charAt(left);
                count[outgoing]--;
                if (count[outgoing] == 0) {
                    distinct--;
                }
                left++;
            }

            best = Math.max(best, right - left + 1);
        }

        return best;
    }
}

import java.util.*;

class Solution {
    public int lengthOfLongestSubstringKDistinct(String s, int k) {
        if (k == 0 || s.isEmpty()) {
            return 0;
        }

        LinkedHashMap<Character, Integer> lastSeen = new LinkedHashMap<>(16, 0.75f, true);
        int left = 0;
        int best = 0;

        for (int right = 0; right < s.length(); right++) {
            char ch = s.charAt(right);
            lastSeen.put(ch, right);

            if (lastSeen.size() > k) {
                Iterator<Map.Entry<Character, Integer>> iterator = lastSeen.entrySet().iterator();
                Map.Entry<Character, Integer> oldest = iterator.next();
                left = oldest.getValue() + 1;
                iterator.remove();
            }

            best = Math.max(best, right - left + 1);
        }

        return best;
    }
}

import java.util.*;

class Solution {
    public int lengthOfLongestSubstringKDistinct(String s, int k) {
        if (k == 0 || s.isEmpty()) {
            return 0;
        }

        int best = 0;
        for (int start = 0; start < s.length(); start++) {
            Set<Character> distinct = new HashSet<>();
            for (int end = start; end < s.length(); end++) {
                distinct.add(s.charAt(end));
                if (distinct.size() > k) {
                    break;
                }
                best = Math.max(best, end - start + 1);
            }
        }

        return best;
    }
}
